n24591.content:
\begin{theorem}[Perfect Completeness]
    \label{thm:sumcheck_perfect_completeness}
    The sum-check protocol satisfies perfect completeness. That is, for any valid input statement and oracle statement satisfying the input relation, the protocol accepts with probability 1.
\end{theorem}

n24592.content:
\begin{theorem}[Knowledge Soundness]
    \label{thm:sumcheck_knowledge_soundness}
    The sum-check protocol satisfies knowledge soundness. The soundness error is bounded by $n \cdot d / |R|$, where $n$ is the number of rounds, $d$ is the degree bound, and $|R|$ is the size of the field.
\end{theorem}

n24593.content:
\begin{theorem}[Round-by-Round Knowledge Soundness]
    \label{thm:sumcheck_rbr_knowledge_soundness_standard}
    The sum-check protocol satisfies round-by-round knowledge soundness with respect to an appropriate state function (to be specified). Each round maintains the security properties compositionally, allowing for modular security analysis.
\end{theorem}

n24594.content:
\begin{definition}[Single Round Protocol]
    \label{def:sumcheck_single_round}
    The $i$-th round of sum-check consists of:
    \begin{enumerate}
        \item \textbf{Input:} A statement containing target value and prior challenges, along with an oracle for the multivariate polynomial
        \item \textbf{Prover's message:} A univariate polynomial $p_i \in R[X]_{\leq d}$
        \item \textbf{Verifier's challenge:} A random element $r_i \gets R$
        \item \textbf{Output:} An updated statement with new target $p_i(r_i)$ and extended challenges
    \end{enumerate}
\end{definition}

n24595.content:
\begin{theorem}[Single Round Completeness]
    \label{thm:sumcheck_single_round_completeness}
    Each individual round of the sum-check protocol is perfectly complete.
\end{theorem}

n24596.content:
\begin{theorem}[Single Round Soundness]
    \label{thm:sumcheck_single_round_soundness}
    Each individual round of the sum-check protocol is sound with error probability at most $d / |R|$, where $d$ is the degree bound and $|R|$ is the size of the field.
\end{theorem}

n24597.content:
\begin{theorem}[Round-by-Round Knowledge Soundness]
    \label{thm:sumcheck_rbr_knowledge_soundness}
    The sum-check protocol satisfies round-by-round knowledge soundness. Each individual round can be analyzed independently, and the soundness error in each round is bounded by $d / |R|$.
\end{theorem}

n24598.content:
\begin{definition}
    \label{def:virtual_sumcheck_round_protocol}
    \begin{enumerate}
        \item In this protocol, the context is a pair $(p, d)$, where $p$ is now a \emph{univariate} polynomial of bounded degree. The predicate / relation is that $p(0) + p(1) = d$.
        \item The prover first sends a univariate polynomial $s$ of the same bounded degree as $p$. In
        the honest case, it would just send $p$ itself.
        \item The verifier samples and sends a random challenge $r \gets R$.
        \item The verifier checks that $s(0) + s(1) = d$. The predicate on the resulting output context
        is that $p(r) = s(r)$.
    \end{enumerate}
\end{definition}

n24599.content:
\begin{theorem}
    The virtual sum-check round protocol is sound.
    \label{thm:virtual_sumcheck_round_protocol_sound}
    \uses{def:soundness, def:virtual_sumcheck_round_protocol}
\end{theorem}

n24600.content:
\begin{theorem}
    The virtual sum-check round protocol is knowledge sound.
    \label{thm:virtual_sumcheck_round_protocol_knowledge_sound}
    \uses{def:knowledge_soundness, def:virtual_sumcheck_round_protocol}
\end{theorem}

n24601.content:
\begin{definition}[State Function]
    \label{def:virtual_sumcheck_round_protocol_state_function}
    The state function for the virtual sum-check round protocol is given by:
\begin{enumerate}
    \item The initial state function is the same as the predicate on the initial context, namely that
    $p(0) + p(1) = d$.
    \item The state function after the prover sends $s$ is the predicate that $p(0) + p(1) = d$ and
    $s(0) + s(1) = d$. Essentially, we add in the verifier's check.
    \item The state function for the output context (after the verifier sends $r$) is the predicate that $s(0) + s(1) = d$ and $p(r) = s(r)$.
\end{enumerate}
    \uses{def:state_function, def:virtual_sumcheck_round_protocol}
\end{definition}

n24602.content:
\begin{theorem}
    The virtual sum-check round protocol is round-by-round sound.
    \label{thm:virtual_sumcheck_round_protocol_rbr_sound}
    \uses{def:round_by_round_soundness, def:virtual_sumcheck_round_protocol, def:virtual_sumcheck_round_protocol_state_function}
\end{theorem}

n24603.content:
\begin{definition}[Ring-switching profile]
  \lean{RingSwitching.RingSwitchingProfile}
  \label{def:ring_switching_profile}
  Fix commutative rings $B$ (small) and $L$ (large) with $L$ a $B$-algebra, and $\kappa \in
  \mathbb{N}$. A \emph{ring-switching profile} consists of:
  \begin{itemize}
    \item a rank-$2^\kappa$ $B$-basis $\beta = (\beta_u)_{u \in \{0,1\}^\kappa}$ of $L$;
    \item a commutative \emph{pack/trace carrier} $A$ that is an $L$-algebra (the type sent on the
      wire);
    \item two ring homomorphisms $\varphi_0, \varphi_1 : L \to A$ for evaluation-point data and
      polynomial coefficients, respectively;
    \item coordinate maps $\mathrm{decomposeColumns}, \mathrm{decomposeRows} : A \to (\{0,1\}^\kappa
      \to L)$;
    \item subject to the two \emph{reconstruction laws}
      \begin{equation}
        z = \sum_{u} \varphi_0(\beta_u)\cdot \varphi_1(\mathrm{decomposeRows}(z)_u).
        \label{eq:rs-rows}
      \end{equation}
      \begin{equation}
        z = \sum_{v} \varphi_0(\mathrm{decomposeColumns}(z)_v)\cdot \varphi_1(\beta_v).
        \label{eq:rs-cols}
      \end{equation}
      for all $z \in A$.
  \end{itemize}
\end{definition}

n24604.content:
\begin{definition}[Tensor-product profile]
  \lean{RingSwitching.tensorProductProfile}
  \uses{def:ring_switching_profile}
  \label{def:tensor_product_profile}
  For any fields $B = K$ and $L$ with a chosen degree-$2^\kappa$ extension basis, the profile takes the
  \emph{tensor carrier} $A := L \otimes_K L$, with $\varphi_0(\alpha) = \alpha \otimes 1$,
  $\varphi_1(\alpha) = 1 \otimes \alpha$, and the coordinate maps given by the $K$-basis coordinates
  for the left ($\beta.\mathrm{baseChange}\,L$) and right ($\mathrm{baseChangeRight}\,\beta$)
  $L$-module structures on $A$, giving columns and rows respectively. Thus
  $z = \sum_v z_v \otimes \beta_v = \sum_u \beta_u \otimes z_u$. Laws \eqref{eq:rs-rows}--\eqref{eq:rs-cols} hold by
  \texttt{Basis.sum\_repr} on these bases and are proven in ArkLib. Binius uses this constructor
  with its binary-tower basis.
\end{definition}

n24605.content:
\begin{definition}[Multilinear packing]
  \lean{RingSwitching.packMLE}
  \uses{def:ring_switching_profile}
  \label{def:pack_mle}
  With $\ell = \ell' + \kappa$, a small-field multilinear $t$ in $\ell$ variables is packed into a
  large-field multilinear $t'$ in $\ell'$ variables by bundling each block of $2^\kappa$ coefficients
  into one $L$-element:
  \[
    t'(w) \;=\; \sum_{v \in \{0,1\}^\kappa} t(v, w)\,\beta_v, \qquad w \in \{0,1\}^{\ell'}.
  \]
\end{definition}

n24606.content:
\begin{definition}[Full ring-switching reduction]
  \lean{RingSwitching.FullRingSwitching.fullOracleReduction}
  \uses{def:ring_switching_profile, def:pack_mle}
  \label{def:full_ring_switching}
  The composition of the batching phase, the core sum-check interaction, and the large-field IOPCS
  invocation.
\end{definition}

n24607.content:
\begin{theorem}[Perfect completeness target]
  \lean{RingSwitching.FullRingSwitching.fullOracleReduction_perfectCompleteness}
  \uses{def:full_ring_switching}
  \label{thm:ring_switching_completeness}
  The full ring-switching oracle reduction is perfectly complete: an honest prover holding a witness
  in the input relation always produces a transcript accepted into the output relation. The honest
  prover's folded $\hat s$ must satisfy the verifier's column check through the packing and
  folded-evaluation identities, in addition to reconstruction law \eqref{eq:rs-cols}. These
  instance-specific identities remain proof obligations in the generic development.
\end{theorem}

n24608.content:
\begin{theorem}[Round-by-round knowledge soundness target]
  \lean{RingSwitching.FullRingSwitching.fullOracleVerifier_rbrKnowledgeSoundness}
  \uses{def:full_ring_switching}
  \label{thm:ring_switching_soundness}
  When $L$ is an integral domain, the full reduction is round-by-round knowledge sound, with the
  additive error
  \[
    \frac{\kappa}{\lvert L\rvert} \;+\; \sum_{\text{rounds}} \frac{2}{\lvert L\rvert} \;+\;
    \frac{1}{\lvert L\rvert} \;+\; \varepsilon_{\mathrm{IOPCS}},
  \]
  matching \cite[\S3.1--3.2]{DP24}. The integral-domain hypothesis is exactly the Schwartz--Zippel
  ingredient (a nonzero degree-$d$ univariate over $L$ has at most $d$ roots).
\end{theorem}

n24609.content:
\begin{definition}[Binary Tower Field]
    \lean{BinaryTower.BTField}
    \label{def:binary_tower_field}
    A binary tower field $\mathcal{T}_{\iota}$ for $\iota \in \mathbb{N}$ is defined inductively as the $\iota$-th field in the sequence of quadratic extensions over the ground field $\mathbb{F}_2$.
    \begin{itemize}
        \item $\mathcal{T}_{0} := \mathbb{F}_{2}$
        \item $\forall \iota > 0$, $\mathcal{T}_{\iota} := \mathcal{T}_{\iota-1}[X_{\iota-1}] / (X_{\iota-1}^{2}+X_{\iota-2} \cdot X_{\iota-1}+1)$, where we conventionally set $X_{-1} := 1$.
    \end{itemize}
\end{definition}

n24610.content:
\begin{theorem}[Irreducible defining polynomial]
    \lean{BinaryTower.polyIrreducible}
    \label{thm:binary_tower_field_irreducible}
    The defining polynomial $X_{\iota-1}^{2}+X_{\iota-2} \cdot X_{\iota-1}+1$ of $\mathcal{T}_{\iota}$ is irreducible over $\mathcal{T}_{\iota-1}$ for all $\iota > 0$.
\end{theorem}

n24611.content:
\begin{theorem}[Binary Tower Fields are fields]
  \lean{BinaryTower.BTFieldIsField, BinaryTower.BTFieldCard, BinaryTower.BTFieldChar2}
  \uses{def:binary_tower_field, thm:binary_tower_field_irreducible}
  We prove that the binary tower fields are finite fields:
  \label{thm:binary_tower_fields_are_fields}
    \begin{itemize}
      \item The ground field $\mathcal{T}_{0} := \mathbb{F}_2$ is a field. For all $\iota > 0$, $\mathcal{T}_{\iota}$ is the quotient ring of $\mathcal{T}_{\iota-1}[X_{\iota-1}]$ by the irreducible polynomial $X_{\iota-1}^{2}+X_{\iota-2} \cdot X_{\iota-1}+1$, therefore $\mathcal{T}_{\iota}$ is a field extension of $\mathcal{T}_{\iota-1}$.
      \item For all $\iota \in \mathbb{N}$, the cardinality of $\mathcal{T}_{\iota}$ is $2^{2^{\iota}}$.
      \item For all $\iota \in \mathbb{N}$, the characteristic of $\mathcal{T}_{\iota}$ is 2.
    \end{itemize}
\end{theorem}

n24612.content:
\begin{definition}[Multilinear Bases for Tower Fields]
    \uses{def:binary_tower_field, thm:binary_tower_fields_are_fields}
    \label{def:multilinear_basis}
    For any tower field $\mathcal{T}_\iota$, we define its canonical bases as follows:
    \begin{itemize}
        \item \textbf{$\mathbb{F}_2$-Basis of $\mathcal{T}_\iota$}: The set of multilinear monomials in the variables $\{X_0, \dots, X_{\iota-1}\}$ forms a basis for $\mathcal{T}_\iota$ as a $2^\iota$-dimensional vector space over $\mathbb{F}_2$. An element is typically stored as a $2^\iota$-bit string corresponding to this basis.
        \item \textbf{$\mathcal{T}_\iota$-Basis of $\mathcal{T}_{\iota+\kappa}$}: For any $\kappa \ge 0$, the set of multilinear monomials in the variables $\{X_\iota, \dots, X_{\iota+\kappa-1}\}$ forms a basis for $\mathcal{T}_{\iota+\kappa}$ as a $2^\kappa$-dimensional vector space over the subfield $\mathcal{T}_\iota$.
    \end{itemize}
\end{definition}

n24613.content:
\begin{definition}[Computable Binary Tower Fields]
  \lean{ConcreteBinaryTower.instFieldConcrete}
  \uses{def:binary_tower_field, def:multilinear_basis, thm:binary_tower_fields_are_fields}
  \label{def:computable_binary_tower_field}
  Building upon the abstract definition of binary tower fields, we define a concrete, computable representation of binary tower fields. This construction, which underpins our formalization, represents each element of the field $\mathcal{T}_\iota$ as a bit vector of length $2^\iota$ corresponding to the coefficients of the multilinear $\mathbb{F}_2$-basis.

  The arithmetic operations on these bit-vector representations are defined as follows:
  \begin{itemize}
      \item \textbf{Addition}: The sum of two elements is defined as the bitwise XOR of their corresponding bit-vector representations.

      \item \textbf{Multiplication (in $\mathcal{T}_\iota$)}: The product of two elements within the same field $\mathcal{T}_\iota$ is defined via a recursive Karatsuba-based algorithm~\cite{FP97}. The complexity of this operation is $\Theta(2^{\log_2(3) \cdot \iota})$.

      \item \textbf{Cross-Level Multiplication}: The product of an element $\alpha \in \mathcal{T}_{\iota+\kappa}$ by a scalar $b \in \mathcal{T}_\iota$ is defined by representing $\alpha$ via its $2^\kappa$ coefficients $(a_u)_{u \in \{0,1\}^\kappa}$ in the $\mathcal{T}_\iota$-basis and performing the multiplication component-wise on those coefficients in the subfield $\mathcal{T}_\iota$. The total complexity is $2^\kappa \cdot \Theta(2^{\log_2(3) \cdot \iota})$.
  \end{itemize}
\end{definition}

