\begin{lemma}\label{fact:geometric_sum}
\lean{Combine.geometric_sum_units}
    Let $\field$ be a field, $r\in\field$ be a field element, $a\in\N$ be a natural number. Then
    \[
    \sum_{i=0}^{a} r^i :=
    \left\{
    \begin{array}{ll}
        \displaystyle\left(\frac{1 - r^{a+1}}{1 - r}\right)
        & \text{if } r \neq 1 \\[6pt]
        a + 1
        & \text{if } r = 1
    \end{array}
    \right.
    \]

\end{lemma}

